using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Object=UnityEngine.Object;
public static partial class ScreenshotFollowupRepair {
 [Serializable]public class SupportHit{public string path,mesh;public Vector3 point,min,max;public float hitY;public bool hit;}
 [Serializable]public class Supports{public string utc;public List<SupportHit> original=new List<SupportHit>(),current=new List<SupportHit>();}
 public static void InspectSourceSupports(){var report=new Supports{utc=DateTime.UtcNow.ToString("o")};var gs=EditorSceneManager.OpenScene(GS);var ds=EditorSceneManager.OpenScene(DS,OpenSceneMode.Additive);var current=All(gs).Concat(All(ds)).ToArray();var source=EditorSceneManager.OpenScene(Source,OpenSceneMode.Additive);foreach(var set in new[]{(All(source),report.original),(current,report.current)})foreach(var point in new[]{new Vector3(75,-1.65f,34.45f),new Vector3(114.57f,2.85f,-10.8f),new Vector3(127.6f,2.9f,-47.7f)})foreach(var t in set.Item1.Where(t=>t.GetComponent<MeshFilter>()&&t.GetComponent<MeshRenderer>())){var b=t.GetComponent<Renderer>().bounds;if(point.x<b.min.x-.1f||point.x>b.max.x+.1f||point.z<b.min.z-.1f||point.z>b.max.z+.1f)continue;if(t.name.StartsWith("SM_fence")||t.name.StartsWith("Railing"))continue;var g=new GameObject("temporary_mesh_support_probe");g.transform.SetPositionAndRotation(t.position,t.rotation);g.transform.localScale=t.lossyScale;var c=g.AddComponent<MeshCollider>();c.sharedMesh=t.GetComponent<MeshFilter>().sharedMesh;Physics.SyncTransforms();bool hit=c.Raycast(new Ray(new Vector3(point.x,b.max.y+1,point.z),Vector3.down),out var h,b.size.y+2);set.Item2.Add(new SupportHit{path=P(t),mesh=AssetDatabase.GetAssetPath(c.sharedMesh),min=b.min,max=b.max,point=point,hit=hit,hitY=hit?h.point.y:-999});Object.DestroyImmediate(g);}File.WriteAllText(Path.Combine(Reports,"screenshot-native-support-details.json"),JsonUtility.ToJson(report,true));EditorSceneManager.OpenScene("Assets/Scenes/Main.unity");EditorApplication.Exit(0);}
}
